head.script:
scwin.trigger1_onclick = function(e) {
    dataList1.setColumnFilter({
        type: 'row',
        colIndex: 'col1',
        key: "a",
        condition: 'and',
        exactMatch: true
    });
};
scwin.trigger2_onclick = function(e) {
    dataList1.setColumnFilter({
        type: 'row',
        colIndex: 'col1',
        key: "a",
        condition: 'and'
    });
};
scwin.trigger3_onclick = function(e) {
    dataList1.clearFilter();
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. Script 탭에서 scwin.trigger1_onclick 부분을 확인한다.
    //1. In the Script tab, check scwin.trigger1_onclick.
    // verify step 1. 코멘트확인
    //1. Review comments
    // Test step 2. scwin.trigger2_onclick 부분을 확인한다.
    //2. Check the scwin.trigger2_onclick section.
    // verify step 2. 코멘트확인
    //2. Confirm comments
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    // verify step 3. 'a' 데이터랑 완전 일치한 데이터가 필터처리된다.  
    //3. The data that matches the 'a' data is filtered.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_cell_0_0').innerText", "a");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_cell_1_0').innerText", "a");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gv1_body_tbody tr').not('.w2grid_hidedRow').length == 2", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 4. filter 초기화 버튼을 클릭한다.
    //4. Click the Reset filter button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    // verify step 4. 설정한 필터가 초기화된다.
    //4. The set filter is initialized.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_cell_0_0').innerText", "aaa");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_cell_1_0').innerText", "a");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_cell_2_0').innerText", "bb");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_cell_3_0').innerText", "a");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_cell_4_0').innerText", "c");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_cell_5_0').innerText", "b");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_cell_6_0').innerText", "d");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_cell_7_0').innerText", "aaaaa");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_cell_8_0').innerText", "c");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_cell_9_0').innerText", "b");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    // verify step 5. 'a' 데이터랑 부분적으로 일치한 데이터가 필터처리된다.
    //5. Data partially matching the 'a' data is filtered.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_cell_0_0').innerText", "aaa");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_cell_1_0').innerText", "a");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_cell_2_0').innerText", "a");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gv1_cell_3_0').innerText", "aaaaa");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gv1_body_tbody tr').not('.w2grid_hidedRow').length == 4", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Created By: Sang.do
    //Created By: 29-Jan-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
